// This relies on the remain-on-exit option being set (which NewTmuxSession does).
func (s *TmuxSession) IsPaneDead() bool {
	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
	out, err := cmd.Output()
	if err != nil {
