//go:build e2e

package tests

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/testutil"
)

func TestPiDoesNotWriteActiveSessionCache(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		if s.Agent.Name() != "pi" {
			t.Skip("Pi-only active-session cache probe")
		}

		session := s.StartSession(t, ctx)
		if session == nil {
			t.Fatal("Pi does not support interactive mode")
		}

		logPath := filepath.Join(s.Dir, ".entire", "logs", "entire.log")
		log, err := os.ReadFile(logPath)
		if err != nil {
			t.Fatalf("read Entire hook log: %v", err)
		}
		if !strings.Contains(string(log), `"hook":"session_start"`) {
			t.Fatalf("session_start hook was not observed in %s", logPath)
		}

		cachePath := filepath.Join(s.Dir, ".entire", "tmp", "pi", "pi-active-session")
		_, err = os.Stat(cachePath)
		if !errors.Is(err, fs.ErrNotExist) {
			t.Fatalf("active-session cache exists while Pi session is still open; stat error = %v", err)
		}
		t.Logf("active-session cache absent while live Pi session is open: %s", cachePath)
	})
}

